script:
// Tells you when a web page changes. Each run fetches the page and keeps a fingerprint of it
// in the schedule's state; when a later run's fingerprint differs, you get a notification.
// With a pattern, only the first part of the page that matches it counts, so a clock or an
// ad elsewhere on the page does not set it off, and the notification shows the new value.
import { createHash } from "node:crypto";

export default async function main(ctx) {
  const { url, pattern } = ctx.inputs;
  const res = await fetch(url, { signal: ctx.signal });
  if (!res.ok) throw new Error(`${url} answered ${res.status}`);
  const page = await res.text();
  const watched = pattern ? page.match(new RegExp(pattern))?.[0] : page;
  if (watched === undefined) throw new Error(`nothing on ${url} matches ${pattern}`);

  const fingerprint = createHash("sha256").update(watched).digest("hex");
  const before = ctx.state.fingerprint;
  ctx.state = { fingerprint }; // saved after the run
  if (before === undefined) return ctx.log(`watching ${url}`);
  if (before === fingerprint) return;
  await ctx.notify({ title: "A page you watch changed", body: pattern ? `${url}\n${watched.slice(0, 300)}` : url });
}
